class Card implements Comparable<Card> {
    private int rank;
    private String suit;

    public Card(int rank, String suit) {
        this.rank = rank;
        this.suit = suit;
    }

    public int getRank() {
        return rank;
    }

    public String getSuit() {
        return suit;
    }

    public String toString() {
        String r;
        if (rank == 1) r = "A";
        else if (rank == 11) r = "J";
        else if (rank == 12) r = "Q";
        else if (rank == 13) r = "K";
        else r = "" + rank;
        return r + suit;
    }

    public int compareTo(Card o) {
        if (rank != o.rank) {
            return rank - o.rank;
        }
        return suit.compareTo(o.suit);
    }
}
